// ============================================================================
//                      >>>  FILL THIS IN. NOTHING ELSE.  <<<
// ============================================================================
// Workflow 3 reads each lead's website and decides whether they belong on the
// list at all. It NEVER writes any part of an email — the copy stays fixed and
// tested. See docs/QUALIFICATION.md for why.
//
// The first two must match Workflow 1 exactly.
// ============================================================================

var SETTINGS = {

  // --- Required — must match Workflow 1 ------------------------------------
  AIRTABLE_BASE_ID: '',
  AIRTABLE_TABLE_NAME: 'Leads',

  // --- Required: your Anthropic API key ------------------------------------
  // Get one at https://console.anthropic.com. The key itself lives in the n8n
  // credential "Anthropic API Key (Header Auth)" (Name: x-api-key), NOT here.
  // This just picks the model.
  CLAUDE_MODEL: '',             // default 'claude-sonnet-5'

  // --- Cost / pace ---------------------------------------------------------
  // Leads checked per run. At the default hourly schedule, 50/run clears
  // 1,200 leads a day for roughly $4 per 1,000.
  QUALIFY_PER_RUN: '',          // default 50
  CLAUDE_EFFORT: '',            // default 'low' — this is a short classification

  // --- Optional ------------------------------------------------------------
  SLACK_WEBHOOK_URL: '',        // blank = no summary posted
  // true = check every lead again, even ones already judged. Costs money.
  FORCE_REQUALIFY: ''           // default false

};

// ============================================================================
//              Nothing below this line needs editing. Ever.
// ============================================================================

// ----- node body: src/nodes/w3-01-config.js -----

// n8n Code node — "W3 Config" (Run Once for All Items)
//


function env(name) {
  try {
    var v = $env[name];
    if (v === undefined || v === null || String(v).trim() === '') return null;
    return String(v).trim();
  } catch (e) {
    return null;
  }
}

function setting(name, fallback) {
  var v = SETTINGS[name];
  if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  var e = env(name);
  return e === null ? fallback : e;
}

function settingNum(name, fallback) {
  var raw = setting(name, null);
  if (raw === null) return fallback;
  var n = Number(raw);
  return isFinite(n) ? n : fallback;
}

function settingBool(name, fallback) {
  var raw = setting(name, null);
  return raw === null ? fallback : /^(1|true|yes|on)$/i.test(raw);
}

var cfg = {
  runId: 'qual_' + new Date().toISOString().replace(/[^0-9]/g, '').slice(0, 14),
  now: new Date().toISOString(),

  airtableApiBase: 'https://api.airtable.com/v0',
  airtableMetaBase: 'https://api.airtable.com/v0/meta',
  baseId: setting('AIRTABLE_BASE_ID', ''),
  tableName: setting('AIRTABLE_TABLE_NAME', 'Leads'),

  claudeEndpoint: 'https://api.anthropic.com/v1/messages',
  claudeVersion: '2023-06-01',
  claudeModel: setting('CLAUDE_MODEL', 'claude-sonnet-5'),
  claudeEffort: setting('CLAUDE_EFFORT', 'low'),
  claudeMaxTokens: settingNum('CLAUDE_MAX_TOKENS', 2000),

  perRunCap: settingNum('QUALIFY_PER_RUN', 50),
  pageCharLimit: settingNum('PAGE_CHAR_LIMIT', 6000),
  fetchTimeoutMs: settingNum('PAGE_FETCH_TIMEOUT_MS', 15000),
  forceRequalify: settingBool('FORCE_REQUALIFY', false),

  slackWebhookUrl: setting('SLACK_WEBHOOK_URL', ''),

  // Published rates for claude-sonnet-5, used only for the cost estimate in
  // the run summary. Update if you switch model.
  pricing: { inputPerMillion: 2.0, outputPerMillion: 10.0 }
};

var missing = [];
if (!cfg.baseId) missing.push('AIRTABLE_BASE_ID');
if (!cfg.tableName) missing.push('AIRTABLE_TABLE_NAME');
if (cfg.perRunCap < 1 || cfg.perRunCap > 500) missing.push('QUALIFY_PER_RUN must be between 1 and 500');
if (missing.length) {
  throw new Error(
    'Setup is incomplete. Open this node ("W3 Config"), scroll to the SETTINGS ' +
    'block at the top, and fill in:\n  - ' + missing.join('\n  - ') +
    '\nNo lead was qualified.'
  );
}

console.log('[' + cfg.runId + '] qualifying up to ' + cfg.perRunCap +
  ' leads with ' + cfg.claudeModel + ' (effort ' + cfg.claudeEffort + ')');

return [{ json: { cfg: cfg } }];

'use strict';
/* =========================================================================
 * GENERATED — do not edit in the n8n UI.
 * Source: src/nodes/w3-02-schema-plan.js + src/lib/{schema}.js
 * Edit the source and run `npm run build`; the tests cover this code.
 * ========================================================================= */

// ----- inlined: src/lib/schema.js -----
/**
 * schema.js — Airtable Metadata API schema check.
 *
 * Contract, in priority order:
 *   1. NEVER touch a user column. `First Name`, `Company Name`, `Email` and
 *      `City` are protected: we do not rename, retype or delete them, and we
 *      never issue a destructive request of any kind. The Metadata API we use
 *      can only CREATE fields and ADD single-select choices.
 *   2. If a system field already exists under a DIFFERENT but workable type
 *      (e.g. `Status` as a plain text column), adopt it as-is and report a
 *      note. Airtable cannot convert a field's type over the API, and
 *      dropping/recreating would destroy data — so we adapt to the base
 *      rather than forcing the base to adapt to us.
 *   3. Only genuinely absent fields are created.
 */

var SCHEMA_STATUS_CHOICES = [
  'New',
  'Invalid',
  'Queued',
  'Sent Email 1',
  'Sent Follow-up 1',
  'Sent Follow-up 2',
  'Replied',
  'Do Not Contact'
];

var SCHEMA_FIT_CHOICES = ['Yes', 'Unsure', 'No', 'Unchecked'];

// Columns owned by the user. Present here purely so we can assert we never
// emit a mutation for them, and so we can warn loudly if one is missing.
var SCHEMA_PROTECTED_FIELDS = ['First Name', 'Company Name', 'Email', 'City'];

/**
 * The fields this system needs.
 *
 * `required` fields are named in the brief. The rest are the bookkeeping the
 * brief's own requirements imply — RFC-5322 threading needs a stored
 * Message-ID, and "ultra-reliable" needs an idempotency key and an error
 * column. Set `MANAGE_OPTIONAL_FIELDS=false` to create only the required set.
 */
function desiredFields(opts) {
  var o = opts || {};
  var tz = o.timeZone || 'utc';
  var dateOpts = {
    dateFormat: { name: 'iso' },
    timeFormat: { name: '24hour' },
    timeZone: 'utc' // store UTC; all display/logic conversion happens in code
  };

  var required = [
    {
      name: 'Status',
      type: 'singleSelect',
      description: 'Outreach state machine. Managed by n8n.',
      options: { choices: SCHEMA_STATUS_CHOICES.map(function (c) { return { name: c }; }) },
      // Adopting a text column is fine: the sequencer compares strings.
      acceptableExistingTypes: ['singleSelect', 'singleLineText', 'multilineText']
    },
    {
      name: 'Last Contacted Date',
      type: 'dateTime',
      description: 'UTC timestamp of the last outbound touch. Managed by n8n.',
      options: dateOpts,
      acceptableExistingTypes: ['dateTime', 'date', 'singleLineText']
    },
    {
      name: 'Verification Status',
      type: 'singleLineText',
      description: 'MillionVerifier verdict: Valid | Risky | Invalid. Managed by n8n.',
      acceptableExistingTypes: ['singleLineText', 'singleSelect', 'multilineText']
    }
  ];

  var optional = [
    {
      name: 'Message ID',
      type: 'singleLineText',
      description: 'RFC 5322 Message-ID of touch 1, so follow-ups thread.',
      acceptableExistingTypes: ['singleLineText', 'multilineText']
    },
    {
      name: 'Thread Subject',
      type: 'singleLineText',
      description: 'Subject of touch 1, reused as "Re: ..." on follow-ups.',
      acceptableExistingTypes: ['singleLineText', 'multilineText']
    },
    {
      name: 'Idempotency Key',
      type: 'singleLineText',
      description: 'recordId:touch of the last committed send. Blocks duplicates on retry.',
      acceptableExistingTypes: ['singleLineText', 'multilineText']
    },
    {
      name: 'Last Error',
      type: 'multilineText',
      description: 'Most recent send/verification failure. Cleared on success.',
      acceptableExistingTypes: ['multilineText', 'singleLineText']
    },
    {
      name: 'Reply Received At',
      type: 'dateTime',
      description: 'UTC timestamp of the inbound reply detected by Workflow 2.',
      options: dateOpts,
      acceptableExistingTypes: ['dateTime', 'date', 'singleLineText']
    }
  ].concat(fitFields(dateOpts));

  void tz;
  return o.manageOptional === false
    ? restrict(required, o.only)
    : restrict(required.concat(optional), o.only);
}

/**
 * Columns written by Workflow 3 (the qualification pass). Kept separate so
 * Workflow 3 can provision just these three and run standalone.
 */
function fitFields(dateOpts) {
  return [
    {
      name: 'Fit',
      type: 'singleSelect',
      description: 'Workflow 3 verdict: Yes | Unsure | No | Unchecked. Only "No" is skipped.',
      options: { choices: SCHEMA_FIT_CHOICES.map(function (c) { return { name: c }; }) },
      acceptableExistingTypes: ['singleSelect', 'singleLineText', 'multilineText']
    },
    {
      name: 'Fit Reason',
      type: 'multilineText',
      description: 'One-line justification from the qualification pass, with evidence.',
      acceptableExistingTypes: ['multilineText', 'singleLineText']
    },
    {
      name: 'Fit Checked At',
      type: 'dateTime',
      description: 'UTC timestamp of the last qualification check.',
      options: dateOpts || { dateFormat: { name: 'iso' }, timeFormat: { name: '24hour' }, timeZone: 'utc' },
      acceptableExistingTypes: ['dateTime', 'date', 'singleLineText']
    }
  ];
}

/** Narrow a field list to a named subset, preserving order. */
function restrict(fields, only) {
  if (!only || !only.length) return fields;
  var wanted = only.map(function (n) { return String(n).toLowerCase(); });
  return fields.filter(function (f) { return wanted.indexOf(f.name.toLowerCase()) !== -1; });
}



/** Find a table by id or (case-insensitive) name in a Metadata API payload. */
function findTable(metaResponse, tableIdOrName) {
  var tables = (metaResponse && metaResponse.tables) || [];
  var needle = String(tableIdOrName || '').trim().toLowerCase();
  for (var i = 0; i < tables.length; i++) {
    var t = tables[i];
    if (t.id === tableIdOrName) return t;
    if (String(t.name || '').toLowerCase() === needle) return t;
  }
  return null;
}

function fieldByName(table, name) {
  var fields = (table && table.fields) || [];
  var needle = String(name).toLowerCase();
  for (var i = 0; i < fields.length; i++) {
    if (String(fields[i].name || '').toLowerCase() === needle) return fields[i];
  }
  return null;
}

/** Choice names already present on an existing singleSelect field. */
function existingChoiceNames(field) {
  var choices = (field && field.options && field.options.choices) || [];
  return choices.map(function (c) { return String(c.name); });
}

/**
 * Compare the live table against `desiredFields()` and produce an
 * executable plan. Pure function: does no I/O, so it is fully unit-testable.
 *
 * @returns {{
 *   tableId: string|null,
 *   createFields: Array,          POST bodies for /meta/.../fields
 *   patchSelectFields: Array,     PATCH bodies that only ADD select choices
 *   adopted: Array,               fields kept under a different-but-usable type
 *   notes: string[],
 *   blocking: string[],           problems a human must resolve
 *   ok: boolean
 * }}
 */
function planSchema(metaResponse, tableIdOrName, opts) {
  var plan = {
    tableId: null,
    tableName: null,
    createFields: [],
    patchSelectFields: [],
    adopted: [],
    notes: [],
    blocking: [],
    ok: false
  };

  var table = findTable(metaResponse, tableIdOrName);
  if (!table) {
    plan.blocking.push(
      'Table "' + tableIdOrName + '" not found in base. Check AIRTABLE_TABLE_NAME ' +
      'and that the PAT has schema.bases:read on this base.'
    );
    return plan;
  }
  plan.tableId = table.id;
  plan.tableName = table.name;

  // Protected user columns: warn, never mutate.
  for (var p = 0; p < SCHEMA_PROTECTED_FIELDS.length; p++) {
    var prot = SCHEMA_PROTECTED_FIELDS[p];
    if (!fieldByName(table, prot)) {
      if (prot === 'Email') {
        plan.blocking.push('Required user column "Email" is missing — nothing can be sent without it.');
      } else {
        plan.notes.push('User column "' + prot + '" is missing. Copy will fall back to its generic variant.');
      }
    }
  }

  var wanted = desiredFields(opts);
  for (var i = 0; i < wanted.length; i++) {
    var spec = wanted[i];
    var existing = fieldByName(table, spec.name);

    if (!existing) {
      var body = { name: spec.name, type: spec.type };
      if (spec.description) body.description = spec.description;
      if (spec.options) body.options = spec.options;
      plan.createFields.push(body);
      continue;
    }

    if (existing.type === spec.type) {
      // Same type. For singleSelect, top up any missing choices additively.
      if (spec.type === 'singleSelect') {
        var have = existingChoiceNames(existing);
        var haveLower = have.map(function (n) { return n.toLowerCase(); });
        var wantChoices = spec.name === 'Fit' ? SCHEMA_FIT_CHOICES : SCHEMA_STATUS_CHOICES;
        var missing = wantChoices.filter(function (c) {
          return haveLower.indexOf(c.toLowerCase()) === -1;
        });
        if (missing.length) {
          // PATCH must echo ALL existing choices (with their ids) plus the new
          // ones, or Airtable rejects the request as a destructive change.
          var choices = ((existing.options && existing.options.choices) || []).map(function (c) {
            return c.id ? { id: c.id, name: c.name } : { name: c.name };
          }).concat(missing.map(function (n) { return { name: n }; }));
          plan.patchSelectFields.push({
            fieldId: existing.id,
            name: existing.name,
            addedChoices: missing,
            body: { options: { choices: choices } }
          });
        }
      }
      continue;
    }

    var acceptable = spec.acceptableExistingTypes || [];
    if (acceptable.indexOf(existing.type) !== -1) {
      plan.adopted.push({ name: spec.name, wanted: spec.type, found: existing.type });
      plan.notes.push(
        'Field "' + spec.name + '" already exists as "' + existing.type + '" (wanted "' +
        spec.type + '"). Adopting it as-is — no data touched.'
      );
      continue;
    }

    plan.blocking.push(
      'Field "' + spec.name + '" exists as "' + existing.type + '", which this system ' +
      'cannot use (needs one of: ' + acceptable.join(', ') + '). Rename or convert it ' +
      'in the Airtable UI — this workflow will not modify it.'
    );
  }

  plan.ok = plan.blocking.length === 0;
  return plan;
}

/**
 * Airtable single-select fields reject unknown option names. When Status is a
 * select whose choices we could not extend, degrade to the closest legal value
 * instead of failing the write.
 */
function coerceStatusValue(value, allowedChoices) {
  if (!allowedChoices || !allowedChoices.length) return value;
  var lower = String(value).toLowerCase();
  for (var i = 0; i < allowedChoices.length; i++) {
    if (String(allowedChoices[i]).toLowerCase() === lower) return allowedChoices[i];
  }
  return null; // caller decides: skip the write rather than corrupt the cell
}

// ----- node body: src/nodes/w3-02-schema-plan.js -----

// n8n Code node — "Plan Fit Columns" (Run Once for All Items)
//
// Provisions only the three columns Workflow 3 writes, so this workflow can be
// run before — or entirely without — Workflow 1. Same contract as Workflow 1's
// schema engine: create missing fields, extend select choices additively,
// never touch a user column, never retype or delete anything.

var cfg = $('W3 Config').first().json.cfg;
var meta = $input.first().json;

var plan = planSchema(meta, cfg.tableName, {
  only: ['Fit', 'Fit Reason', 'Fit Checked At']
});

if (!plan.ok) {
  throw new Error(
    'Cannot prepare the qualification columns:\n  - ' + plan.blocking.join('\n  - ') +
    '\nNothing was changed.'
  );
}

var items = [];
for (var i = 0; i < plan.createFields.length; i++) {
  items.push({
    json: {
      op: 'create-field',
      label: 'CREATE ' + plan.createFields[i].name,
      method: 'POST',
      url: cfg.airtableMetaBase + '/bases/' + cfg.baseId + '/tables/' + plan.tableId + '/fields',
      body: plan.createFields[i]
    }
  });
}
for (var p = 0; p < plan.patchSelectFields.length; p++) {
  var patch = plan.patchSelectFields[p];
  items.push({
    json: {
      op: 'patch-choices',
      label: 'ADD CHOICES to ' + patch.name + ': ' + patch.addedChoices.join(', '),
      method: 'PATCH',
      url: cfg.airtableMetaBase + '/bases/' + cfg.baseId + '/tables/' + plan.tableId + '/fields/' + patch.fieldId,
      body: patch.body
    }
  });
}

items.push({
  json: {
    op: 'plan-summary',
    tableId: plan.tableId,
    tableName: plan.tableName,
    created: plan.createFields.map(function (f) { return f.name; }),
    choicesAdded: plan.patchSelectFields.map(function (f) { return f.name; }),
    adopted: plan.adopted,
    notes: plan.notes
  }
});

return items;

'use strict';
/* =========================================================================
 * GENERATED — do not edit in the n8n UI.
 * Source: src/nodes/w3-03-schema-report.js + src/lib/{qualify}.js
 * Edit the source and run `npm run build`; the tests cover this code.
 * ========================================================================= */

// ----- inlined: src/lib/qualify.js -----
/**
 * qualify.js — the lead qualification pass (Workflow 3).
 *
 * What this does and, more importantly, what it does NOT do.
 *
 * It reads a company's website and decides whether they belong on the list at
 * all. It does not write, suggest, or influence a single word of the email.
 * That separation is deliberate:
 *
 *  - Generated openers ("I came across your portfolio of transitional kitchen
 *    remodels...") are the most recognizable pattern in cold email. They read
 *    as more of a pitch, not less.
 *  - Anything a model writes into a live email is untestable. The rest of this
 *    system is deterministic and covered by tests; a hallucinated detail in a
 *    cold email is not recoverable.
 *  - Targeting is where the leverage actually is at 30 sends/day. Not sending
 *    to a roofer beats any amount of clever phrasing.
 *
 * So the model answers narrow factual questions, the answer lands in a column,
 * and Workflow 1 skips the clear mismatches. Fixed copy, better list.
 *
 * FAIL-OPEN, everywhere. A dead site, a timeout, an API outage, a blocked
 * scraper — all resolve to "Unsure", which is still contacted. Only an
 * explicit "No" is skipped. Never running Workflow 3 at all leaves Workflow 1
 * behaving exactly as it did before.
 */

// This module deliberately depends on NOTHING else. Reaching for templates.js
// (which has an identical whitespace helper) would inline the entire email copy
// into Workflow 3's nodes, and the one property this workflow must have is that
// the model cannot reach a single word that goes to a prospect.

/** Mailbox providers whose domain tells us nothing about the business. */
var QL_FREEMAIL = [
  'gmail.com', 'googlemail.com', 'yahoo.com', 'ymail.com', 'hotmail.com',
  'outlook.com', 'live.com', 'msn.com', 'aol.com', 'icloud.com', 'me.com',
  'mac.com', 'comcast.net', 'verizon.net', 'att.net', 'sbcglobal.net',
  'bellsouth.net', 'cox.net', 'charter.net', 'earthlink.net', 'protonmail.com',
  'proton.me', 'gmx.com', 'mail.com', 'yandex.com', 'zoho.com'
];

var QL_VERDICTS = ['Yes', 'Unsure', 'No'];

var QL_CATEGORIES = [
  'kitchen_bath_remodeler', 'general_contractor', 'handyman',
  'supplier_showroom', 'designer_only', 'other_trade', 'not_a_business',
  'unknown'
];

var QL_SIZES = ['solo', 'small_team', 'established', 'unknown'];

function qlTrim(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

/** Collapse whitespace and strip control characters. Local by design. */
function qlTidy(value) {
  if (value === null || value === undefined) return '';
  return String(value)
    .replace(/[\u0000-\u001F\u007F]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Domain half of an email address, lowercased. */
function domainOf(email) {
  var at = qlTrim(email).toLowerCase().split('@');
  return at.length === 2 && at[1] ? at[1] : null;
}

function isFreemail(email) {
  var d = domainOf(email);
  return d ? QL_FREEMAIL.indexOf(d) !== -1 : false;
}

/**
 * Where to look for this company's site.
 *
 * A `Website` column wins if the user has one. Otherwise the email domain is a
 * good guess for a small contractor — dana@mapleridgekitchens.com is almost
 * certainly mapleridgekitchens.com. A free mailbox tells us nothing, so those
 * leads are left unchecked rather than guessed at.
 */
function resolveUrl(lead) {
  var explicit = qlTrim(lead && (lead.website || lead['Website'] || lead['Site'] || lead['URL']));
  if (explicit) {
    var url = explicit;
    if (!/^https?:\/\//i.test(url)) url = 'https://' + url.replace(/^\/+/, '');
    if (/^https?:\/\/[^\s/.]+\.[^\s/]{2,}/i.test(url)) {
      return { url: url.split('#')[0], source: 'website-column' };
    }
    return { url: null, source: 'website-column', reason: 'Website column is not a usable URL.' };
  }

  var email = qlTrim(lead && (lead.email || lead['Email']));
  if (!email) return { url: null, source: 'none', reason: 'No website and no email address.' };
  if (isFreemail(email)) {
    return { url: null, source: 'freemail', reason: 'Free mailbox (' + domainOf(email) + ') — no company site to read.' };
  }
  var d = domainOf(email);
  if (!d || d.indexOf('.') === -1) {
    return { url: null, source: 'email-domain', reason: 'Email domain is unusable.' };
  }
  return { url: 'https://' + d, source: 'email-domain' };
}

/**
 * HTML -> readable text.
 *
 * Scripts, styles, nav chrome and SVG are dropped first: they are most of the
 * bytes and none of the signal, and every token we send costs money.
 */
function htmlToText(html, maxChars) {
  var limit = maxChars || 6000;
  var text = String(html || '');

  var title = '';
  var titleMatch = /<title[^>]*>([\s\S]{0,300}?)<\/title>/i.exec(text);
  if (titleMatch) title = titleMatch[1];

  var description = '';
  var descMatch = /<meta[^>]+name=["']description["'][^>]*content=["']([\s\S]{0,400}?)["']/i.exec(text);
  if (descMatch) description = descMatch[1];

  var body = text
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<\/(p|div|li|h[1-6]|tr|section|article)>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&quot;/gi, '"')
    .replace(/[ \t ]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();

  var head = [];
  if (title) head.push('PAGE TITLE: ' + qlTidy(title));
  if (description) head.push('META DESCRIPTION: ' + qlTidy(description));
  var joined = (head.length ? head.join('\n') + '\n\n' : '') + body;

  return {
    title: qlTidy(title),
    description: qlTidy(description),
    text: joined.slice(0, limit),
    truncated: joined.length > limit,
    originalLength: joined.length
  };
}

/**
 * Is there enough on the page to judge anything?
 * A parked domain, a JS-only shell or a 404 gives us nothing, and asking the
 * model to guess from 40 words produces confident nonsense.
 */
function isUsablePage(page, minChars) {
  var min = minChars || 200;
  if (!page || !page.text) return false;
  var words = page.text.replace(/\s+/g, ' ').trim();
  if (words.length < min) return false;
  if (/domain (is )?(for sale|parked)|buy this domain|coming soon|under construction|website is being/i.test(words.slice(0, 600))) {
    return false;
  }
  return true;
}

